export function shoppingPlanHTML(s,plan,query,limit,{E,esc,picture}){
 const st=E.storeById(plan.store),summary=E.shoppingPlanSummary(s,plan),candidates=E.shoppingPlanCandidates(s,plan.store,{category:plan.category,query,limit}),saved=s.shoppingPlans.find(p=>p.store===plan.store),dirty=!saved||JSON.stringify([saved.category,saved.budget,saved.items])!==JSON.stringify([plan.category,plan.budget,plan.items]);
 return `<div class="modal-body shopping-planner"><div class="planner-intro"><span class="eyebrow">ORIGINAL MALLSIDE SHOPPING DESK</span><h3>A little plan before the next shop.</h3><p>Build a shortlist using verified products at their named shops in ${esc(E.mallOf(s).name)}. This lounge’s own collection is still in research. Planning is free; time pauses here.</p></div><div class="planner-settings"><fieldset><legend>Your game budget, including tax</legend><div class="planner-buttons">${E.PLAN_BUDGETS.map(n=>`<button class="button secondary" data-action="plan-budget" data-id="${n}" aria-pressed="${plan.budget===n}">${E.money(n)}</button>`).join('')}</div></fieldset><fieldset><legend>Browse a category</legend><div class="planner-buttons">${E.shoppingPlanCategories(plan.store).map(c=>`<button class="button secondary" data-action="plan-category" data-id="${esc(c)}" aria-pressed="${plan.category===c}">${c==='all'?'All finds':esc(c)}</button>`).join('')}</div></fieldset></div><section class="plan-shortlist" aria-label="Your shortlist"><div class="plan-tally ${summary.over?'over-budget':''}" role="status"><strong>${plan.items.length}/3 finds · ${E.money(summary.total)} including tax</strong><span>${summary.over?E.money(-summary.remaining)+' over your plan':E.money(summary.remaining)+' remaining'}</span></div>${summary.lines.map(({p,total,owned})=>`<article><span><strong>${esc(p.name)}</strong><small>${esc(E.storeById(p.store).name)} · ${E.money(total)} with tax${owned?' · Already purchased ✓':''}</small></span><button class="button secondary small" data-action="plan-remove" data-id="${esc(p.id)}" aria-label="Remove ${esc(p.name)}">Remove</button></article>`).join('')||'<p>No picks yet. Add up to three finds below.</p>'}<div class="service-links"><button class="button orange" data-action="plan-save" ${dirty?'':'disabled'}>Save shortlist${dirty?'':' ✓'}</button><button class="button secondary" data-action="plan-notebook">My shortlists · ${s.shoppingPlans.length}/16</button></div><p class="hint">Saving spends no money and reserves no stock. Prices may change before checkout. Walking to a find leaves this lounge and opens its real shop.</p>${saved&&!dirty&&summary.lines.length?`<div class="plan-route">${summary.lines.map(({p},i)=>`<button class="button secondary wide" data-action="plan-walk" data-id="${esc(p.id)}">${i+1}. Walk to ${esc(E.storeById(p.store).name)} · ${esc(p.name)}</button>`).join('')}</div>`:''}</section><form id="plan-search-form" class="planner-search"><label for="plan-query">Find a product, brand or shop</label><div><input id="plan-query" type="search" maxlength="100" value="${esc(query)}"><button class="button secondary" type="submit">Search</button></div></form><div class="planner-products">${candidates.map(p=>`<article><div class="product-art">${picture(p,{mini:true})}</div><small>AVAILABLE AT ${esc(E.storeById(p.store).name)}</small><h3>${esc(p.name)}</h3><strong>${E.money(E.price(s,p))}</strong><p>${esc(E.planFor(s).levels[E.storeFloor(E.mallOf(s),p.store)])}</p><button class="button secondary wide" data-action="plan-add" data-id="${esc(p.id)}" ${plan.items.includes(p.id)||plan.items.length>=3?'disabled':''}>${plan.items.includes(p.id)?'In your shortlist ✓':'Add to shortlist'}</button></article>`).join('')||'<p>No verified finds match this search. Try All finds or another search.</p>'}</div>${candidates.length===limit&&limit<60?'<button class="button secondary wide" data-action="plan-more">Show more verified finds</button>':''}<button class="text-button" data-action="plan-back">Back to this shop’s guide</button></div>`;
}
export function shoppingPlanNotebook(s,{E,esc}){return `<div class="modal-body plan-notebook"><p>Your saved shortlists. Each find belongs to its named shop; checkout happens there. Prices below reflect today’s game prices.</p>${s.shoppingPlans.map(p=>{const st=E.storeById(p.store),sum=E.shoppingPlanSummary(s,p),mall=E.mallForStore(s,st.id);return `<article><small>Day ${p.day} · ${esc(mall.name)}</small><h3>${esc(st.name)} · ${p.items.length}/3 finds</h3><p>${E.money(sum.total)} including tax · budget ${E.money(p.budget)}</p>${sum.lines.map(l=>`<p>${esc(l.p.name)}<br><small>${esc(E.storeById(l.p.store).name)}${l.owned?' · Purchased ✓':''}</small></p>`).join('')}<div class="service-links"><button class="button secondary" data-action="plan-reopen" data-id="${esc(p.store)}">${s.mallId===mall.id?'Open shortlist':'Walk to this planning lounge'}</button><button class="text-button" data-action="plan-delete" data-id="${esc(p.store)}">Remove shortlist</button></div></article>`;}).join('')||'<p>No shortlists yet. Enter a planning lounge to build your first one.</p>'}</div>`;}
